{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw
img = Image.open('radiograph.jpg').convert('RGB')
d = ImageDraw.Draw(img)
# grid every 100 px, labels every 200
for x in range(0, img.width, 100):
    d.line([(x,0),(x,img.height)], fill=(255,0,0), width=2 if x%200==0 else 1)
    if x%200==0: d.text((x+3, 5), str(x), fill=(255,255,0))
for y in range(0, img.height, 100):
    d.line([(0,y),(img.width,y)], fill=(255,0,0), width=2 if y%200==0 else 1)
    if y%200==0: d.text((5, y+3), str(y), fill=(255,255,0))
img.save('crops/grid.png')
# left and right halves
img.crop((0,0,1222,1292)).save('crops/grid_L.png')
img.crop((1222,0,2444,1292)).save('crops/grid_R.png')
EOF", "description": "Overlay coordinate grid on radiograph"}
